import sys

def solve() -> None:
    stack = []  # each element is (value, current_min)
    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        if line == "exit":
            break
        if line.startswith("push"):
            parts = line.split()
            if len(parts) >= 2:
                try:
                    x = int(parts[1])
                except ValueError:
                    continue
                if not stack:
                    stack.append((x, x))
                else:
                    cur_min = stack[-1][1]
                    stack.append((x, x if x < cur_min else cur_min))
        elif line == "pop":
            if stack:
                stack.pop()
        elif line.startswith("get"):
            if stack:
                print(stack[-1][1])

if __name__ == "__main__":
    solve()
